  'taxes.meterEyebrow': { 'pt-BR':'ARRECADÔMETRO AUDITÁVEL', en:'AUDITABLE TAX METER', es:'RECAUDÓMETRO AUDITABLE', de:'PRÜFBARER STEUERZÄHLER', fr:'COMPTEUR FISCAL AUDITABLE', ru:'ПРОВЕРЯЕМЫЙ НАЛОГОВЫЙ СЧЁТЧИК', 'zh-CN':'可审计税收计数器', ja:'監査可能な税収メーター', ko:'감사 가능한 세수 계량기', pl:'WERYFIKOWALNY LICZNIK PODATKOWY' },
  'taxes.meterTitle': { 'pt-BR':'Carga tributária acumulada estimada em {year}', en:'Estimated accumulated tax burden in {year}', es:'Carga tributaria acumulada estimada en {year}', de:'Geschätzte kumulierte Steuerlast {year}', fr:'Charge fiscale cumulée estimée en {year}', ru:'Оценка накопленной налоговой нагрузки в {year} г.', 'zh-CN':'{year}年累计税收负担估算', ja:'{year}年の推定累積税負担', ko:'{year}년 추정 누적 조세 부담', pl:'Szacowane skumulowane obciążenie podatkowe w {year} r.' },
  'taxes.estimate': { 'pt-BR':'ESTIMATIVA LINEAR', en:'LINEAR ESTIMATE', es:'ESTIMACIÓN LINEAL', de:'LINEARE SCHÄTZUNG', fr:'ESTIMATION LINÉAIRE', ru:'ЛИНЕЙНАЯ ОЦЕНКА', 'zh-CN':'线性估算', ja:'線形推計', ko:'선형 추정', pl:'SZACUNEK LINIOWY' },
  'taxes.perSecond': { 'pt-BR':'Por segundo', en:'Per second', es:'Por segundo', de:'Pro Sekunde', fr:'Par seconde', ru:'В секунду', 'zh-CN':'每秒', ja:'1秒当たり', ko:'초당', pl:'Na sekundę' },
