  'taxes.ledgerTitle': { 'pt-BR':'Criações, novas incidências e substituições', en:'Creations, new incidences and replacements', es:'Creaciones, nuevas incidencias y sustituciones', de:'Neuschaffungen, neue Tatbestände und Ersetzungen', fr:'Créations, nouvelles incidences et remplacements', ru:'Новые налоги, новые объекты и замены', 'zh-CN':'新设、扩大征收与替代', ja:'新設・新たな課税・置換', ko:'신설, 신규 부과 및 대체', pl:'Nowe daniny, nowe zakresy i zastąpienia' },
  'taxes.ledgerDescription': { 'pt-BR':'“Quem deu a ideia” é registrado como autor formal da proposição. Emendas constitucionais são promulgadas pelo Congresso, não sancionadas pelo presidente.', en:'“Who proposed it” means the formal author of the bill. Constitutional amendments are enacted by Congress, not sanctioned by the president.', es:'“Quién lo propuso” significa el autor formal. Las enmiendas constitucionales las promulga el Congreso, no las sanciona el presidente.', de:'„Urheber“ meint den formellen Antragsteller. Verfassungsänderungen werden vom Kongress verkündet, nicht vom Präsidenten sanktioniert.', fr:'« Qui l’a proposé » désigne l’auteur formel. Les amendements constitutionnels sont promulgués par le Congrès, non sanctionnés par le président.', ru:'«Кто предложил» означает формального автора. Конституционные поправки провозглашает Конгресс, а не президент.', 'zh-CN':'“谁提出”指正式提案人。宪法修正案由国会颁布，并非总统签署批准。', ja:'「誰が提案したか」は正式な提出者を指します。憲法修正は大統領の裁可ではなく議会が公布します。', ko:'“누가 제안했는가”는 공식 발의자를 뜻합니다. 헌법 개정은 대통령 재가가 아니라 의회가 공포합니다.', pl:'„Kto zaproponował” oznacza formalnego autora projektu. Poprawki konstytucyjne ogłasza Kongres, a nie sankcjonuje prezydent.' },
  'taxes.proposal': { 'pt-BR':'Proposição', en:'Proposal', es:'Propuesta', de:'Vorlage', fr:'Proposition', ru:'Законопроект', 'zh-CN':'提案', ja:'法案', ko:'법안', pl:'Projekt' },
