  'guide.what': { 'pt-BR':'O que é?', en:'What is it?', es:'¿Qué es?', de:'Was ist das?', fr:'Qu’est-ce que c’est ?', ru:'Что это?', 'zh-CN':'这是什么？', ja:'何を示す？', ko:'무엇인가요?', pl:'Co to jest?' },
  'guide.read': { 'pt-BR':'Como ler?', en:'How do I read it?', es:'¿Cómo se interpreta?', de:'Wie liest man ihn?', fr:'Comment le lire ?', ru:'Как читать?', 'zh-CN':'如何阅读？', ja:'どう読む？', ko:'어떻게 읽나요?', pl:'Jak to odczytać?' },
  'guide.caution': { 'pt-BR':'Atenção', en:'Keep in mind', es:'Atención', de:'Wichtig', fr:'Attention', ru:'Важно', 'zh-CN':'请注意', ja:'注意点', ko:'주의', pl:'Uwaga' },
  'guide.readText': { 'pt-BR':'No gráfico, cada ponto corresponde a {name} em {unit}. A série é {frequency}; confira o período ao lado do valor.', en:'On the chart, each point is {name} in {unit}. The series is {frequency}; check the period shown with the value.', es:'En el gráfico, cada punto corresponde a {name} en {unit}. La serie es {frequency}; compruebe el período junto al valor.', de:'Im Diagramm steht jeder Punkt für {name} in {unit}. Die Reihe ist {frequency}; beachten Sie den Zeitraum beim Wert.', fr:'Sur le graphique, chaque point correspond à {name} en {unit}. La série est {frequency} ; vérifiez la période associée à la valeur.', ru:'На графике каждая точка показывает {name} в {unit}. Частота ряда — {frequency}; смотрите период рядом со значением.', 'zh-CN':'图中每个点表示以{unit}计的{name}。序列频率为{frequency}；请同时查看数值对应的期间。', ja:'グラフの各点は{unit}で表した{name}です。系列は{frequency}で、値と期間を一緒に確認してください。', ko:'차트의 각 점은 {unit} 단위의 {name}입니다. 시계열은 {frequency}이며 값과 함께 기간을 확인하세요.', pl:'Na wykresie każdy punkt oznacza {name} w {unit}. Szereg ma częstotliwość {frequency}; sprawdź okres podany przy wartości.' },
  'guide.cautionText': { 'pt-BR':'Compare valores somente quando definição, unidade e período forem equivalentes. Lacunas não significam zero.', en:'Compare values only when definition, unit and period are equivalent. A missing value does not mean zero.', es:'Compare valores solo cuando la definición, la unidad y el período sean equivalentes. Un dato ausente no significa cero.', de:'Vergleichen Sie Werte nur bei gleicher Definition, Einheit und Periode. Fehlende Werte bedeuten nicht null.', fr:'Ne comparez que des valeurs ayant la même définition, unité et période. Une donnée manquante ne signifie pas zéro.', ru:'Сравнивайте значения только при одинаковых определении, единице и периоде. Пропуск не означает ноль.', 'zh-CN':'只有定义、单位和时期一致时才能比较。缺失值不代表零。', ja:'定義・単位・期間が同じ場合にのみ比較してください。欠損値はゼロではありません。', ko:'정의, 단위, 기간이 같은 값만 비교하세요. 결측치는 0을 뜻하지 않습니다.', pl:'Porównuj wartości tylko przy zgodnej definicji, jednostce i okresie. Brak danych nie oznacza zera.' },
